def main() -> None:
    files = json.loads(zlib.decompress(base64.b85decode(PAYLOAD)).decode("utf-8"))
    for relative, content in files.items():
        path = Path(relative)
        if not path.is_file():
            raise FileNotFoundError(relative)
        path.write_text(content, encoding="utf-8")


if __name__ == "__main__":
    main()
